def load() -> pd.DataFrame:
    import pandas as pd
    import numpy as np
    from cdflib import CDF

    path = 'data/astronomy/input/swarm/SW_OPER_ACCACAL_2__20240511T000000_20240511T235959_0304.cdf'
    cdf = CDF(path)

    info = cdf.cdf_info()
    vars_ = []
    for attr in ['rVariables', 'zVariables']:
        v = getattr(info, attr, None)
        if v:
            vars_.extend(list(v))

    # pick likely time variables
    time_like = [v for v in vars_ if ('epoch' in v.lower()) or (v.lower() == 'time') or ('time' in v.lower())]
    # pick likely acceleration variables
    acc_like = [v for v in vars_ if v.lower().startswith('a_') or 'acc' in v.lower()]

    rows = []
    for v in time_like[:8]:
        try:
            arr = np.asarray(cdf.varget(v))
            rows.append({'var': v, 'shape': str(arr.shape), 'dtype': str(arr.dtype), 'min': str(np.nanmin(arr) if arr.size else None), 'max': str(np.nanmax(arr) if arr.size else None), 'sample0': str(arr.flat[0] if arr.size else None)})
        except Exception as e:
            rows.append({'var': v, 'shape': None, 'dtype': None, 'min': None, 'max': None, 'sample0': f'ERROR: {e}'})

    for v in acc_like[:12]:
        try:
            arr = np.asarray(cdf.varget(v))
            finite = arr[np.isfinite(arr)] if np.issubdtype(arr.dtype, np.number) else np.array([])
            rows.append({'var': v, 'shape': str(arr.shape), 'dtype': str(arr.dtype), 'min': str(np.nanmin(finite) if finite.size else None), 'max': str(np.nanmax(finite) if finite.size else None), 'sample0': str(arr.flat[0] if arr.size else None)})
        except Exception as e:
            rows.append({'var': v, 'shape': None, 'dtype': None, 'min': None, 'max': None, 'sample0': f'ERROR: {e}'})

    return pd.DataFrame(rows)
